import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { DocumentTab } from '../../interfaces/individual.interface';
import { environment } from '../../../../environments/environment';
import { shareLink } from '../../interfaces/sharelink.interface';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';

@Injectable({
  providedIn: 'root'
})
export class IndividualService {
  isAdjustDoc: boolean = false;
  constructor(private http: HttpClient, private store: SecureStorageService) { }


  async getTabinfo(data: string[]): Promise<DocumentTab[]> {
    const params = new HttpParams().set('jFiles', JSON.stringify(data));
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.get<DocumentTab[]>(
          `${environment.cloudUrl}${environment.coreservice}/individual/tabinfo`, { params: params }
        )
      );
    } catch (error) {
      console.error(error)
      res = [];
    }
    return res;
  }

  async fetchPreNextDocs(nBundledetailid: string, cFlag: string, jAvoid: string[]) {
    let params = new HttpParams().set('nBundledetailid', nBundledetailid);
    params = params.set('cFlag', cFlag);
    params = params.set('jAvoid', JSON.stringify(jAvoid));
    let res: any = {};
    try {
      res = await firstValueFrom(
        this.http.get<DocumentTab>(
          `${environment.cloudUrl}${environment.coreservice}/individual/gettab`, { params: params }
        )
      );
      if (res.msg == -1) {
        return null;
      }
    } catch (error) {
      res = null;
    }
    return res;
  }

  updateUrl(documents: DocumentTab[], nCaseid: string, nPresentid: string, nIndexid: string) {
    const tabs = documents.map(a => ([a.nBundledetailid, a.onPage || 1, a.jFSids || null, a.nRFSid || null, a.nRDocid || null, a.nRWebid || null, a.jFilter, null, a.isActivate ? true : false, a.nSesid || null]));
    const url: any = [tabs, nCaseid];
    if (nPresentid)
      url.push(nPresentid);
    if (nIndexid)
      url.push(nIndexid);

    

    const path: string | URL = `/individual/doc/${encodeURIComponent(JSON.stringify(url))}`; //[tabs, nCaseid, nPresentid, nIndexid]

    // const ids = documents.map(a => a.nBundledetailid);
    this.store.setStorage(`INDIVIDUAL:${nCaseid}`, 1);
    window.history.pushState("", "Individual Doc - Etabella", path);
  }

  async sharedusers(nBundledetailid: string) {
    let params = new HttpParams().set('nBundledetailid', nBundledetailid);
    let res: any = {};
    try {
      res = await firstValueFrom(
        this.http.get<DocumentTab>(
          `${environment.cloudUrl}${environment.coreservice}/individual/locationshare/sharedusers`, { params: params }
        )
      );
      if (res.msg == -1) {
        return null;
      }
    } catch (error) {
      res = null;
    }
    return res;
  }

  async update_sharelink(mdl): Promise<boolean> {
    let res: any;
    try {
      res = await firstValueFrom(
        this.http.post<shareLink>(`${environment.cloudUrl}${environment.coreservice}/individual/updatesharelink`, mdl)
      );
      if (res[0].msg == -1) {
        return null;
      }
    } catch (error) {
      res = null;
    }
    return res;
  }

  async shared_to_users(mdl): Promise<any> {
    let res: any;
    try {
      res = await firstValueFrom(
        this.http.post<shareLink>(`${environment.cloudUrl}${environment.coreservice}/individual/locationshare/sharetousers`, mdl)
      );
      if (res.msg != 1) {
        return null;
      }
    } catch (error) {
      res = null;
    }
    return res;
  }

  async fetchAllDocs(ids: any) {
    let params = new HttpParams().set('jDocids', JSON.stringify(ids));
    let res: any = {};
    try {
      res = await firstValueFrom(
        this.http.get<DocumentTab>(
          `${environment.cloudUrl}${environment.coreservice}/doclink/docdetail`, { params: params }
        )
      );
      if (res.msg == -1) {
        return null;
      }
    } catch (error) {
      res = null;
    }
    return res;
  }

}